#!/bin/sh
# Knowledge Base source. A KB takes one query per dataset, so the three kinds of
# claim (owner incidents, author descriptions, community rules) come from one union.
# Kept on one line: npx on Windows drops everything after a newline in an argument.
# Every matched document counts toward the org's indexed-document cap (150 in beta).
KB=${KB:?set KB to the knowledge base id}

npx sanity context imports create $KB --sanity-project 49jweiga --sanity-dataset production --query '*[ _type == "incident" || (_type == "mod" && packageId in ["spino.megafauna", "spincrus.dinosauria", "mehni.pickupandhaul", "jecrell.doorsexpanded", "sarg.alphaanimals", "cabbage.rimcities", "sarg.alphabiomes", "kentington.saveourship2", "vanillaexpanded.vcef", "mlie.simplymorebridges", "mlie.variousspaceshipchunk", "mlie.foodalert", "spdskatr.projectrimfactory", "zylle.mapdesigner", "usagirei.pocketsand", "mlie.xndprofitableweapons", "mlie.showmeyourhands", "archoran.utils.vpeautoplow", "amch.deconstructpercentage", "iworosiak.holsters", "mlie.icantfixthat", "vanillaexpanded.vpsycastse", "captainmuscles.semirandomresearch.unofficial", "vanillaracesexpanded.saurid", "mlie.yayoscaravan", "sks.litters", "adamas.hospitalitycasino", "alleykat.persistentprecepts", "zed.0xff.loftbed", "vanillaracesexpanded.sanguophage", "mlie.betterbeggars", "zal.musicmanager", "fuu.bloodanimations", "defaults.1trickpwnyta", "zal.cloning", "memegoddess.runandgun"]) || (_type == "rule" && defined(note) && subject.mod._ref in *[_id == "modlist-current"][0].entries[].mod._ref) ]{ _type == "incident" => {"kind": "owner incident", title, date, symptom, signature, cause, fix, verdict, "mods": mods[]{packageId, "title": mod->title}}, _type == "mod" => {"kind": "author description", title, packageId, authors, supportedVersions, description, "dependencies": dependencies[].packageId, "loadAfter": loadAfter[].packageId, "loadBefore": loadBefore[].packageId, "incompatibleWith": incompatibleWith[].packageId}, _type == "rule" => {"kind": "RimSort community rule", relation, note, "subject": subject.packageId, "subjectTitle": subject.mod->title, "target": target.packageId, "targetTitle": coalesce(target.mod->title, target.displayName)} }'
